<?php
declare(strict_types=1);
require_once __DIR__.'/_admin_auth.php';require_once __DIR__.'/../../includes/work_tracker.php';header('Content-Type: application/json; charset=utf-8');
$q=mb_strtolower(trim((string)($_GET['q']??'')));$jobId=max(0,(int)($_GET['job_id']??0));if(mb_strlen($q)<2){echo json_encode(['results'=>[]]);exit;}$base=($_SERVER['HTTP_HOST']??'')==='localhost'?'/mike_of_all_trades':'';
$jobUrl=fn(string $page,string $suffix='')=>$jobId?$base.'/admin/work/'.$page.'?id='.$jobId.$suffix:$base.'/admin/work/index.php?find='.rawurlencode($q);
$tools=[['Calendar','bookings schedule appointments events',$base.'/admin/dashboard.php','Admin tool'],['Work Tracker','jobs customers work customer search',$base.'/admin/work/index.php','Admin tool'],['Create a new job','new job add customer import booking',$base.'/admin/work/new.php','Action'],['AI estimates','ai quote estimate pricing',$base.'/admin/ai_estimates.php','Admin tool'],['Social slideshow reel builder','slideshow reel video social tiktok instagram youtube',$jobUrl('social_video_builder.php'),'Job tool'],['Social drafts','social post caption draft facebook instagram',$jobUrl('social_drafts.php'),'Job tool'],['Task photos','photo photos before progress after upload',$jobUrl('task_photos.php'),'Job tool'],['Materials, receipts and reimbursements','receipt supplier material bunnings reimbursement',$jobUrl('materials.php'),'Job tool'],['Pricing and agreement','price pricing rate scope agreement signature variation',$jobUrl('manage_job.php','#pricing-agreement'),'Job section'],['Timers and work activity','timer time stop earlier forgotten activity session',$jobUrl('manage_job.php','#live-timer'),'Job section'],['Invoice preparation','invoice billing payment outstanding',$jobUrl('invoice_preparation.php'),'Job tool']];
$results=[];foreach($tools as [$title,$keywords,$url,$type])if(str_contains(mb_strtolower($title.' '.$keywords),$q))$results[]=['title'=>$title,'description'=>$type,'url'=>$url,'type'=>'tool'];
$stmt=$pdo->prepare("SELECT id,customer_name,customer_email,customer_phone,job_address,status FROM work_jobs WHERE LOWER(CONCAT_WS(' ',id,customer_name,customer_email,customer_phone,job_address)) LIKE ? ORDER BY COALESCE(last_opened_at,updated_at) DESC LIMIT 12");$stmt->execute(['%'.$q.'%']);foreach($stmt->fetchAll(PDO::FETCH_ASSOC) as $j)$results[]=['title'=>'Job #'.$j['id'].' — '.$j['customer_name'],'description'=>trim((string)($j['job_address']??'')).' · '.(string)$j['status'],'url'=>$base.'/admin/work/manage_job.php?id='.(int)$j['id'],'type'=>'job'];echo json_encode(['results'=>array_slice($results,0,20)],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);
